@import url('https://testingcf.jsdelivr.net/npm/lxgw-wenkai-webfont@1.7.0/lxgwwenkai-regular.css');
@import url('https://testingcf.jsdelivr.net/npm/lxgw-wenkai-webfont@1.7.0/lxgwwenkai-bold.css');
@import url('https://testingcf.jsdelivr.net/npm/lxgw-wenkai-webfont@1.7.0/lxgwwenkaimono-regular.css');
/* ================================================================
 * 402 宿舍 —— Unpacking 风的像素宿舍（施工中）
 *
 * 设计与实现：Claude Opus 5.5（Anthropic）
 * 借鉴 Unpacking（Witch Beam）的 UI 结构：房间浮在深色方格底上，界面是放在房间前面的纸。
 * 宿舍像素画是新画的（PixelLab 生成后整理），不含 Unpacking 的美术素材、名字和图标。
 *
 * 结构：
 *   深色方格底 → 宿舍（放大 3 倍、压暗）→ 一本学生用笺（聊天）
 *   面板是撕下来的纸：中间那些从左边滑出，左右两个照旧贴边
 *   装「主题伴侣」扩展后：顶栏多一个「房间」按钮，进去以后房间里的东西就是菜单
 *
 * 改颜色：「用户设置 → UI 主题」的颜色选择器
 *   主要文字 = 墨水；斜体 = 旁白的淡墨；引号 = 台词（绿笔）；下划线 = 红笔（校名、邮戳、开着的东西）
 *   聊天背景色 = 房间外面的深色底；模糊背景色 = 纸
 *
 * 字体：霞鹜文楷（OFL）
 * ================================================================ */

/* ================================================================
 * 可改区：想调整的都在这里，改完点空白处即可生效。改坏了重新导入主题就能恢复。
 * ================================================================ */
html:root {
    --dm-school: "江城大学";            /* 信笺抬头 */
    --dm-address: "桂园 7 栋 402";      /* 信笺底下印的地址 */
    --dm-dim: 0.5;                     /* 聊天时房间压暗多少：0 不暗 / 1 全黑 */
    --dm-room-scale: 3;                /* 聊天时房间放大几倍（只用整数，不然像素会糊）*/
    --dm-room-y: -40px;                /* 房间往上挪多少 */
    --dm-lh: 34px;                     /* 正文行高 = 横线的间距 */
    --dm-text-size: 17px;              /* 正文字号 */
    --dm-pad-x: 36px;                  /* 纸的左右留白 */
    --dm-sheet-w: 620px;               /* 从左边滑出来的面板宽度 */
    --dm-avatar: 44px;                 /* 头像大小 */
    --dm-font: "LXGW WenKai", "霞鹜文楷", "KaiTi", "Microsoft YaHei", sans-serif;
    --dm-mono: "LXGW WenKai Mono", "LXGW WenKai", monospace;
}

@media screen and (max-width: 1000px) {
    html:root {
        --dm-room-scale: 2;
        --dm-room-y: -20px;
        --dm-lh: 30px;
        --dm-text-size: 15.5px;
        --dm-pad-x: 14px;
        --dm-avatar: 36px;
    }
}
/* ======================== 可改区结束 ======================== */

