/* ==== themes/dorm/base.css ==== */
/* ---------------- 色板（全部从酒馆的颜色变量推出来）---------------- */
:root {
    --dm-ink: var(--SmartThemeBodyColor);
    --dm-ink2: var(--SmartThemeEmColor);
    --dm-quote: var(--SmartThemeQuoteColor);
    --dm-red: var(--SmartThemeUnderlineColor);
    --dm-paper: var(--SmartThemeBlurTintColor);
    --dm-void: var(--SmartThemeChatTintColor);
    --dm-line: var(--SmartThemeBorderColor);
    --dm-void2: color-mix(in srgb, var(--dm-void), white 5%);
    --dm-hud: color-mix(in srgb, var(--dm-void), #e6e4ff 62%);
    --dm-hud-hi: color-mix(in srgb, var(--dm-void), #fff 92%);
    --dm-paper-edge: color-mix(in srgb, var(--dm-paper), var(--dm-ink) 14%);
    --dm-paper-low: color-mix(in srgb, var(--dm-paper), var(--dm-ink) 6%);
    --dm-rule-red: color-mix(in srgb, var(--dm-paper), var(--dm-red) 30%);
    --dm-rule-blue: color-mix(in srgb, var(--dm-paper), #4a78b8 28%);
    --dm-margin-red: linear-gradient(90deg, transparent calc(var(--dm-pad-x) + var(--dm-avatar) + 4px), color-mix(in srgb, var(--dm-paper), var(--dm-red) 45%) 0 calc(var(--dm-pad-x) + var(--dm-avatar) + 6px), transparent 0);
    --dm-glue-color: color-mix(in srgb, var(--dm-red), black 35%);
    --dm-note: #f6e7a6;

    /* 纸张选项（主题设置里换纸时改这几个）*/
    --dm-rule: var(--dm-rule-red);
    --dm-head-display: block;
    --dm-glue: 12px;
    --dm-margin-bg: none;
    --dm-tape-display: none;
    --dm-foot-display: block;

    --dm-room: var(--dm-room-girl);
    --dm-tiles: conic-gradient(var(--dm-void) 25%, var(--dm-void2) 0 50%, var(--dm-void) 0 75%, var(--dm-void2) 0) 0 0 / 64px 64px;

    --mainFontFamily: var(--dm-font);
    --monoFontFamily: var(--dm-mono);
}

html body {
    font-family: var(--dm-font);
    background: var(--dm-void);
}

* {
    text-shadow: none !important;
}

/* ---------------- 房间：深色方格底上的宿舍，聊天时放大、压暗 ---------------- */
#bg1,
#bg_custom {
    background:
        linear-gradient(rgb(14 15 34 / var(--dm-dim)), rgb(14 15 34 / var(--dm-dim))),
        var(--dm-room) 50% var(--dm-room-y) / calc(448px * var(--dm-room-scale)) auto no-repeat,
        var(--dm-tiles) !important;
    image-rendering: pixelated;
    opacity: 1 !important;
    filter: none !important;
}

#bg_custom {
    display: none !important;
}

/* ---------------- 顶栏：房间外面的几颗淡紫色小图标 ---------------- */
/* 顶栏底下垫一条深色方格（和房间外面的底对齐），图标不压在房间上 */
#top-bar {
    background: var(--dm-tiles) !important;
    background-attachment: fixed !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    border: 0 !important;
}

#top-settings-holder .drawer-icon {
    color: var(--dm-hud);
    opacity: 1 !important;
    transition: color var(--animation-duration) ease;
}

#top-settings-holder .drawer-icon:hover,
#top-settings-holder .drawer-icon.openIcon {
    color: var(--dm-hud-hi);
}

#top-settings-holder .drawer-icon.openIcon {
    filter: drop-shadow(0 3px 0 var(--dm-red));
}

/* 图标换成 16×16 的实心像素剪影，画的是房间里对应的东西（别的扩展加的图标不认识，照旧用字体图标） */
#top-settings-holder .drawer-icon.fa-cube { --dm-ico: var(--ico-room); }
#top-settings-holder .drawer-icon.fa-sliders { --dm-ico: var(--ico-strip); }
#top-settings-holder .drawer-icon.fa-plug { --dm-ico: var(--ico-monitor); }
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation { --dm-ico: var(--ico-monitorx); }
#top-settings-holder .drawer-icon.fa-font { --dm-ico: var(--ico-thermos); }
#top-settings-holder .drawer-icon.fa-book-atlas { --dm-ico: var(--ico-note); }
#top-settings-holder .drawer-icon.fa-user-cog { --dm-ico: var(--ico-lamp); }
#top-settings-holder .drawer-icon.fa-panorama { --dm-ico: var(--ico-window); }
#top-settings-holder .drawer-icon.fa-cubes { --dm-ico: var(--ico-box); }
#top-settings-holder .drawer-icon.fa-face-smile { --dm-ico: var(--ico-mirror); }
#top-settings-holder .drawer-icon.fa-address-card { --dm-ico: var(--ico-closet); }

#top-settings-holder .drawer-icon.fa-cube::before,
#top-settings-holder .drawer-icon.fa-sliders::before,
#top-settings-holder .drawer-icon.fa-plug::before,
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation::before,
#top-settings-holder .drawer-icon.fa-font::before,
#top-settings-holder .drawer-icon.fa-book-atlas::before,
#top-settings-holder .drawer-icon.fa-user-cog::before,
#top-settings-holder .drawer-icon.fa-panorama::before,
#top-settings-holder .drawer-icon.fa-cubes::before,
#top-settings-holder .drawer-icon.fa-face-smile::before,
#top-settings-holder .drawer-icon.fa-address-card::before {
    content: "" !important;
    display: block;
    width: 32px;
    height: 32px;
    margin: auto;
    background: currentColor;
    -webkit-mask: var(--dm-ico) center / 32px 32px no-repeat;
    mask: var(--dm-ico) center / 32px 32px no-repeat;
}

/* 手机上顶栏挤：图标 24×24*/
@media screen and (max-width: 1000px) {
    #top-settings-holder .drawer-icon.fa-cube::before,
#top-settings-holder .drawer-icon.fa-sliders::before,
#top-settings-holder .drawer-icon.fa-plug::before,
#top-settings-holder .drawer-icon.fa-plug-circle-exclamation::before,
#top-settings-holder .drawer-icon.fa-font::before,
#top-settings-holder .drawer-icon.fa-book-atlas::before,
#top-settings-holder .drawer-icon.fa-user-cog::before,
#top-settings-holder .drawer-icon.fa-panorama::before,
#top-settings-holder .drawer-icon.fa-cubes::before,
#top-settings-holder .drawer-icon.fa-face-smile::before,
#top-settings-holder .drawer-icon.fa-address-card::before {
        width: 24px;
        height: 24px;
        -webkit-mask-size: 24px 24px;
        mask-size: 24px 24px;
    }
}

/* ---------------- 字体、链接 ---------------- */
body,
input,
textarea,
select,
button,
.menu_button:not([class*="fa-"]),
.text_pole {
    font-family: var(--dm-font);
}

a {
    color: var(--dm-red);
}

::selection {
    background: color-mix(in srgb, var(--dm-note), transparent 10%);
    color: var(--dm-ink);
}
/* ==== end themes/dorm/base.css ==== */
/* ==== themes/dorm/chat.css ==== */
/* ---------------- 聊天：一本学生用笺 ---------------- */
#sheld {
    background: var(--dm-paper);
    border: 2px solid var(--dm-line);
    border-top: calc(var(--dm-glue) + 2px) solid var(--dm-glue-color);
    /* 底下压着的几页纸 */
    box-shadow:
        0 4px 0 var(--dm-paper-edge), 0 6px 0 var(--dm-line),
        0 9px 0 var(--dm-paper-edge), 0 11px 0 var(--dm-line),
        10px 16px 0 rgb(0 0 0 / 0.28);
}

@media screen and (min-width: 1001px) {
    #sheld {
        top: calc(var(--topBarBlockSize) + 4px);
        height: calc(100dvh - var(--topBarBlockSize) - 28px);
        max-height: calc(100dvh - var(--topBarBlockSize) - 28px);
    }
}

/* 抬头：校名 + 「学 生 用 笺」+ 一道红色双线 */
#sheld::before,
#sheld::after {
    display: var(--dm-head-display);
    flex: none;
    text-align: center;
    color: var(--dm-red);
    pointer-events: none;
}

#sheld::before {
    order: -2;
    content: var(--dm-school);
    padding-top: 12px;
    font-size: 26px;
    font-weight: 700;
    letter-spacing: 0.5em;
    text-indent: 0.5em;
    line-height: 1.3;
}

#sheld::after {
    order: -1;
    content: "学 生 用 笺";
    margin: 0 var(--dm-pad-x);
    padding-bottom: 6px;
    font-size: 12px;
    letter-spacing: 0.2em;
    border-bottom: 3px double var(--dm-red);
    opacity: 0.85;
}

@media screen and (max-width: 1000px) {
    #sheld::before {
        font-size: 20px;
        padding-top: 6px;
    }

    #sheld::after {
        font-size: 11px;
        padding-bottom: 4px;
    }
}

#chat {
    background: var(--dm-margin-bg) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: 0 !important;
    box-shadow: none !important;
    padding: 0 calc(var(--dm-pad-x) - 10px) 0 calc(var(--dm-pad-x) - 10px);
}

/* 作业纸：两角贴胶带（电脑上贴在纸的上沿）*/
@media screen and (min-width: 1001px) {
    body::before,
    body::after {
        content: "";
        display: var(--dm-tape-display);
        position: fixed;
        z-index: 32;
        top: calc(var(--topBarBlockSize) - 8px);
        width: 110px;
        height: 26px;
        background: color-mix(in srgb, #efe2b4, transparent 18%);
        border: 2px solid color-mix(in srgb, var(--dm-line), transparent 72%);
        pointer-events: none;
    }

    body::before {
        left: calc((100dvw - var(--sheldWidth)) / 2 + 50px);
        transform: rotate(-4deg);
    }

    body::after {
        right: calc((100dvw - var(--sheldWidth)) / 2 + 50px);
        transform: rotate(3deg);
    }
}

/* ---------------- 每条消息 ---------------- */
#chat .mes {
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    padding: calc(var(--dm-lh) * 0.5) 10px 0;
    gap: 0 12px;
}

#chat .mes .mesAvatarWrapper .avatar {
    width: var(--dm-avatar);
    height: var(--dm-avatar);
    border-radius: 0 !important;
    border: 2px solid var(--dm-line);
    background: var(--dm-paper-low);
    box-shadow: 2px 2px 0 rgb(0 0 0 / 0.12);
    transform: rotate(-3deg);
    overflow: hidden;
    flex: none;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
    transform: rotate(2deg);
}

#chat .mes .avatar img {
    width: 100%;
    height: 100%;
    border-radius: 0 !important;
    object-fit: cover;
    image-rendering: pixelated;
}

#chat .mes .ch_name .name_text {
    font-weight: 700;
    font-size: 15px;
    color: var(--dm-ink);
}

#chat .mes .timestamp,
#chat .mes .mesIDDisplay,
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay {
    color: var(--dm-ink2);
    opacity: 1;
    font-size: 12px;
}

#chat .mes .mes_buttons,
#chat .mes .extraMesButtonsHint,
#chat .mes .swipe_left,
#chat .mes .swipe_right,
#chat .mes .swipes-counter {
    color: var(--dm-ink2);
}

/* 正文写在横线上：每行底下一道线，行高 = 线距 */
#chat .mes_text {
    font-size: var(--dm-text-size);
    line-height: var(--dm-lh);
    color: var(--dm-ink);
    padding-bottom: 0;
    background-image: repeating-linear-gradient(to bottom, transparent 0 calc(var(--dm-lh) - 1px), var(--dm-rule) calc(var(--dm-lh) - 1px) var(--dm-lh));
}

#chat .mes_text p,
#chat .mes_text li,
#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4,
#chat .mes_text h5,
#chat .mes_text h6,
#chat .mes_text blockquote {
    line-height: var(--dm-lh);
    margin-top: 0;
    margin-bottom: 0;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4,
#chat .mes_text h5,
#chat .mes_text h6 {
    font-size: 1em;
    font-weight: 700;
}

#chat .mes_text em,
#chat .mes_text i {
    color: var(--dm-ink2);
    font-style: normal;
}

#chat .mes_text q {
    color: var(--dm-quote);
}

#chat .mes_text strong,
#chat .mes_text b {
    font-weight: 700;
}

#chat .mes_text u {
    text-decoration-color: var(--dm-red);
    text-decoration-thickness: 2px;
    text-underline-offset: 4px;
}

/* 横线之外的东西（代码块、表格、引用、图片）盖一块纸，不让线穿过去；高度凑成线距的整数倍 */
#chat .mes_text pre,
#chat .mes_text table,
#chat .mes_text blockquote,
#chat .mes_text img,
#chat .mes_text hr {
    margin-block: calc(var(--dm-lh) * 0.5);
}

#chat .mes_text pre {
    background: var(--dm-paper-low) !important;
    border: 2px dashed color-mix(in srgb, var(--dm-line), transparent 55%);
    border-radius: 0;
    padding: 0;
}

#chat .mes_text pre code {
    display: block;
    padding: 8px 12px;
    font-family: var(--dm-mono);
    font-size: 0.92em;
    line-height: 1.6;
    color: var(--dm-ink);
    background: transparent !important;
}

#chat .mes_text code:not(pre code) {
    font-family: var(--dm-mono);
    background: var(--dm-paper-low);
    border: 1px solid color-mix(in srgb, var(--dm-line), transparent 65%);
    border-radius: 0;
    padding: 0 4px;
    color: var(--dm-ink);
}

#chat .mes_text table {
    background: var(--dm-paper);
    border-collapse: collapse;
}

#chat .mes_text th,
#chat .mes_text td {
    border: 1px solid color-mix(in srgb, var(--dm-line), transparent 50%);
    padding: 2px 10px;
    line-height: calc(var(--dm-lh) - 6px);
}

#chat .mes_text th {
    background: var(--dm-paper-low);
}

#chat .mes_text blockquote {
    background: var(--dm-paper);
    border-left: 3px solid var(--dm-red);
    padding-left: 12px;
    margin-inline: 0;
}

/* 推理块：一张夹在本子里的便签 */
#chat .mes_reasoning_details {
    background: color-mix(in srgb, var(--dm-note), var(--dm-paper) 30%);
    border: 0;
    border-radius: 0;
    box-shadow: 2px 3px 0 rgb(0 0 0 / 0.12);
    margin: 4px 0 calc(var(--dm-lh) * 0.5);
    color: var(--dm-ink);
}

#chat .mes_reasoning_details .mes_reasoning_summary,
#chat .mes_reasoning_details .mes_reasoning {
    color: var(--dm-ink);
}

/* ---------------- 写字的地方：纸底下一道线，「寄」字邮戳发送 ---------------- */
#form_sheld {
    margin: 0 var(--dm-pad-x);
    width: auto;
    border-top: 2px solid var(--dm-line);
}

#form_sheld::after {
    content: var(--dm-address);
    display: var(--dm-foot-display);
    padding: 4px 0 8px;
    border-top: 1px solid var(--dm-rule);
    color: var(--dm-red);
    opacity: 0.8;
    font-size: 12px;
}

#send_form {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    margin: 0;
    padding-block: 6px;
}

#send_textarea {
    background: transparent !important;
    color: var(--dm-ink);
    font-size: var(--dm-text-size);
    line-height: 1.7;
}

#send_textarea::placeholder {
    color: var(--dm-ink2);
    opacity: 1;
}

#leftSendForm > div,
#rightSendForm > div {
    color: var(--dm-ink2);
    opacity: 1;
}

#rightSendForm #send_but {
    display: grid;
    place-items: center;
    width: 36px;
    height: 36px;
    border: 2px solid var(--dm-red);
    border-radius: 50%;
    color: var(--dm-red);
    transform: rotate(-8deg);
}

#rightSendForm #send_but.displayNone {
    display: none;
}

#send_but::before {
    content: "寄";
    font-family: var(--dm-font);
    font-weight: 700;
    font-size: 16px;
}
/* ==== end themes/dorm/chat.css ==== */
/* ==== themes/dorm/panels.css ==== */
/* ---------------- 面板：撕下来的纸 ---------------- */
.drawer-content,
#left-nav-panel,
#right-nav-panel {
    background-color: var(--dm-paper) !important;
    color: var(--dm-ink);
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

@media screen and (min-width: 1001px) {
    /* 中间那些面板（API、高级格式、用户设置、背景、扩展、人设）：从左边滑出来，右边是撕边。世界书条目多、要宽，留在原位 */
    .drawer-content:not(.fillLeft):not(.fillRight):not(#WorldInfo) {
        left: 0 !important;
        right: auto !important;
        margin: 0 !important;
        width: var(--dm-sheet-w) !important;
        padding: 18px 34px 18px 22px;
        clip-path: var(--dm-torn-right);
    }

    /* 世界书留在原位，下边撕开 */
    #WorldInfo {
        padding-bottom: 24px;
        clip-path: var(--dm-torn-bottom);
    }

    #left-nav-panel {
        padding-right: 22px;
        clip-path: var(--dm-torn-right);
    }

    #right-nav-panel {
        padding-left: 22px;
        clip-path: var(--dm-torn-left);
    }
}

/* 预设、角色两个侧边面板一直伸到屏幕底：酒馆从顶上（手机是顶栏下面）开始，高度却扣掉了顶栏，底下空一截 */
:root {
    --dm-nav-top: 0px;
}

@media screen and (max-width: 1000px) {
    :root {
        --dm-nav-top: var(--topBarBlockSize);
    }
}

#left-nav-panel,
#right-nav-panel {
    max-height: calc(100dvh - var(--dm-nav-top)) !important;
}

#left-nav-panel.openDrawer,
#right-nav-panel.openDrawer {
    height: calc(100dvh - var(--dm-nav-top)) !important;
}

/* 标题、分隔线 */
.drawer-content h3,
.drawer-content h4,
.standoutHeader {
    color: var(--dm-ink);
    font-weight: 700;
}

.standoutHeader {
    background: transparent !important;
    border: 0 !important;
    border-bottom: 2px solid var(--dm-ink2) !important;
    border-radius: 0 !important;
}

hr,
.drawer-content hr {
    border-color: color-mix(in srgb, var(--dm-line), transparent 70%);
}

/* ---------------- 控件 ---------------- */
.menu_button {
    background: var(--dm-paper) !important;
    color: var(--dm-ink) !important;
    border: 2px solid var(--dm-line) !important;
    border-radius: 3px !important;
    box-shadow: 2px 2px 0 color-mix(in srgb, var(--dm-line), transparent 70%);
    opacity: 1 !important;
    filter: none !important;
}

.menu_button:hover {
    background: var(--dm-paper-low) !important;
}

.menu_button.active,
.menu_button.toggleEnabled {
    background: var(--dm-note) !important;
}

.text_pole,
textarea.text_pole,
select.text_pole,
#send_form select {
    background: var(--dm-paper) !important;
    color: var(--dm-ink) !important;
    border: 0 !important;
    border-bottom: 2px solid color-mix(in srgb, var(--dm-line), transparent 45%) !important;
    border-radius: 0 !important;
}

.text_pole:focus,
.text_pole:focus-visible {
    outline: none;
    border-bottom-color: var(--dm-red) !important;
}

input[type="checkbox"] {
    accent-color: var(--dm-red);
}

input[type="range"] {
    accent-color: var(--dm-ink);
}

/* ---------------- 世界书：开着的条目是钉着的黄便利贴，关着的是没贴的灰纸 ---------------- */
#world_popup_entries_list .world_entry {
    background: var(--dm-note);
    border: 0;
    border-radius: 0;
    box-shadow: 2px 3px 0 rgb(0 0 0 / 0.14);
    margin-block: 8px;
}

#world_popup_entries_list .world_entry.disabledWIEntry {
    background: color-mix(in srgb, var(--dm-paper), var(--dm-ink) 7%);
    box-shadow: none;
    outline: 2px dashed color-mix(in srgb, var(--dm-ink2), transparent 50%);
    outline-offset: -2px;
}

/* 酒馆给关掉的条目整条压淡：撤掉，改成灰纸 + 虚线，标题照样清楚；右上角写「没贴」 */
#world_popup_entries_list .world_entry.disabledWIEntry,
#world_popup_entries_list .world_entry.disabledWIEntry * {
    opacity: 1 !important;
    filter: none !important;
}

#world_popup_entries_list .world_entry.disabledWIEntry :is(textarea, input, select, .text_pole) {
    color: var(--dm-ink) !important;
}

#world_popup_entries_list .world_entry.disabledWIEntry .inline-drawer-header {
    position: relative;
}

#world_popup_entries_list .world_entry.disabledWIEntry .inline-drawer-header::after {
    content: "没贴";
    position: absolute;
    right: 6px;
    top: -6px;
    padding: 0 6px;
    font-size: 12px;
    line-height: 18px;
    color: var(--dm-ink2);
    border: 1px solid var(--dm-ink2);
    background: var(--dm-paper);
    transform: rotate(3deg);
    pointer-events: none;
}

/* 中间的面板打开时，信笺往后退一点（压暗），撕边才看得出来 */
@media screen and (min-width: 1001px) {
    body:has(.drawer-content.openDrawer:not(.fillLeft):not(.fillRight)) #sheld {
        filter: brightness(0.82);
    }

    #sheld {
        transition: filter var(--animation-duration-2x) ease;
    }
}

/* ---------------- 预设条目：开着的是黄便签，关着的是灰纸 ---------------- */
#completion_prompt_manager_list li.completion_prompt_manager_prompt {
    border-radius: 0;
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    background: color-mix(in srgb, var(--dm-note), var(--dm-paper) 35%);
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
    background: transparent;
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    opacity: 1 !important;
    color: var(--dm-ink2) !important;
}

/* ---------------- 弹窗：一张纸 ---------------- */
dialog.popup {
    background: var(--dm-paper) !important;
    color: var(--dm-ink);
    border: 2px solid var(--dm-line) !important;
    border-radius: 0 !important;
    box-shadow: 8px 10px 0 rgb(0 0 0 / 0.3) !important;
}

dialog.popup::backdrop {
    background: rgb(14 15 34 / 0.55);
    backdrop-filter: none;
}

.popup-button-ok.menu_button,
.popup-button-cancel.menu_button {
    background: var(--dm-paper) !important;
}

.popup-button-ok.menu_button {
    border-color: var(--dm-red) !important;
    color: var(--dm-red) !important;
}

/* ---------------- 滚动条：只在电脑上，细细一条墨 ---------------- */
@media screen and (min-width: 1001px) {
    ::-webkit-scrollbar-thumb:vertical,
    ::-webkit-scrollbar-thumb:horizontal {
        background-color: color-mix(in srgb, var(--dm-ink2), transparent 45%);
        border-radius: 0;
    }
}

@media screen and (max-width: 1000px) {
    ::-webkit-scrollbar {
        width: 0;
        height: 0;
    }
}

/* ---------------- 酒馆默认压淡的字（对比度不够）---------------- */
#completion_prompt_manager .completion_prompt_manager_header {
    color: var(--dm-ink2);
}

#chat .mes .swipes-counter {
    color: var(--dm-ink2) !important;
    opacity: 1 !important;
}

/* 小字：酒馆是正文色 × 0.7，换成旁白的淡墨（不透明，对比度够）*/
small {
    color: var(--dm-ink2);
    opacity: 1;
}

#rm_button_selected_ch,
#version_display {
    opacity: 1;
}

#rm_button_selected_ch h2,
#version_display {
    color: var(--dm-ink2) !important;
}

/* 大的输入框（角色描述、编辑消息……）：浅一档的纸，细框 */
textarea:not(#send_textarea),
#chat .mes .edit_textarea {
    background: var(--dm-paper-low) !important;
    color: var(--dm-ink) !important;
    border: 1px solid color-mix(in srgb, var(--dm-line), transparent 60%) !important;
    border-radius: 0 !important;
}

textarea::placeholder {
    color: var(--dm-ink2);
    opacity: 1;
}

/* 停止键：红笔 */
#mes_stop {
    color: var(--dm-red);
    opacity: 1;
}
/* ==== end themes/dorm/panels.css ==== */
/* ==== shared/topinfobar.css ==== */
/* 官方扩展「Chat Top Bar」（https://github.com/SillyTavern/Extension-TopInfoBar）的适配
 * 它在聊天上面插一条 #extensionTopBar：聊天列表侧栏、连接配置、聊天名（下拉切换）、搜索、
 * 聊天管理、新建、改名、删除、关闭；点插头图标再往下展开一条 #extensionConnectionProfiles。
 * 没装这个扩展时这些规则什么也不碰。
 *
 * 扩展的 CSS 是网页载入后才插进 <head> 的，排在主题后面，所以这里都加 html body 提权重。
 * 颜色、尺寸全走下面的 --tib-* 变量（默认取 st-fixes 的 --fx-*），主题在自己的 :root 里改：
 *   --tib-h        条高            --tib-pad     左右内边距        --tib-gap   图标间距
 *   --tib-bg       条底            --tib-line    条下边线          --tib-radius 条圆角
 *   --tib-ink      聊天名、悬停图标  --tib-sub     图标、占位字      --tib-accent 开着的图标、搜索框聚焦
 *   --tib-font     字体            --tib-size    字号              --tib-name-weight 聊天名字重
 *   --tib-btn      图标按钮边长     --tib-btn-radius 按钮圆角        --tib-hover 按钮悬停底
 *   --tib-field-*  搜索框：bg 底 / line 边 / radius 圆角 / h 高
 *   --tib-item-radius  聊天列表侧栏里每一项的圆角
 *   --tib-menu-bg、--tib-menu-ink  下拉菜单里的选项（手机和部分浏览器用系统菜单，管不到）
 *   --tib-mark-bg、--tib-mark-ink  搜索时正文里高亮的字 */
:root {
    --tib-h: 36px;
    --tib-pad: 10px;
    --tib-gap: 6px;
    --tib-bg: transparent;
    --tib-line: var(--fx-hairline, var(--SmartThemeBorderColor));
    --tib-radius: 0;
    --tib-ink: var(--fx-ink, var(--SmartThemeBodyColor));
    --tib-sub: var(--fx-meta, var(--SmartThemeBodyColor));
    --tib-accent: var(--fx-accent, var(--SmartThemeQuoteColor));
    --tib-font: inherit;
    --tib-size: 13px;
    --tib-name-weight: 600;
    --tib-btn: 26px;
    --tib-btn-radius: var(--fx-radius, 0);
    --tib-hover: var(--fx-surface, transparent);
    --tib-field-bg: var(--fx-surface, transparent);
    --tib-field-line: transparent;
    --tib-field-radius: var(--fx-radius, 0);
    --tib-field-h: 24px;
    --tib-item-radius: var(--fx-radius, 0);
    --tib-menu-bg: var(--SmartThemeBlurTintColor);
    --tib-menu-ink: var(--SmartThemeBodyColor);
    --tib-mark-bg: color-mix(in srgb, var(--tib-accent) 32%, transparent);
    --tib-mark-ink: inherit;
}

html body #extensionTopBar,
html body #extensionConnectionProfiles {
    height: var(--tib-h);
    margin: 0;
    padding: 0 var(--tib-pad);
    gap: var(--tib-gap);
    align-items: center;
    align-content: center;
    flex-wrap: nowrap;
    border: 0;
    border-bottom: 1px solid var(--tib-line);
    border-radius: var(--tib-radius);
    background: var(--tib-bg);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: none;
    color: var(--tib-ink);
    font-family: var(--tib-font);
    font-size: var(--tib-size);
}

html body #extensionConnectionProfiles {
    display: none;
}

html body #extensionConnectionProfiles.visible {
    display: flex;
}

/* 图标：实色（酒馆的 .right_menu_button 默认半透明） */
html body #extensionTopBar > .right_menu_button,
html body #extensionConnectionProfiles > i {
    flex: none;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--tib-btn);
    height: var(--tib-btn);
    margin: 0;
    padding: 0;
    border-radius: var(--tib-btn-radius);
    color: var(--tib-sub);
    font-size: 14px;
    opacity: 1;
    filter: none;
    text-shadow: none;
    transition: color .15s, background-color .15s;
}

html body #extensionTopBar > .right_menu_button:hover,
html body #extensionTopBar > .right_menu_button:focus-visible {
    color: var(--tib-ink);
    background-color: var(--tib-hover);
    filter: none;
}

/* 打开着的（聊天列表侧栏、连接配置那一条） */
html body #extensionTopBar > .right_menu_button.active {
    color: var(--tib-accent);
    filter: none;
}

/* 没在聊天里（欢迎页）时灰掉的按钮 */
html body #extensionTopBar > .right_menu_button.not-in-chat {
    opacity: .35;
}

/* 聊天名 / 连接配置：下拉框。扩展用的是一张白色小箭头图，浅色主题看不见，换成跟字同色的两道斜线 */
html body #extensionTopBarChatName,
html body #extensionConnectionProfilesSelect {
    flex: 1 1 auto;
    min-width: 0;
    width: auto;
    height: var(--tib-field-h);
    margin: 0;
    padding: 0 22px 0 4px;
    border: 0;
    border-radius: var(--tib-btn-radius);
    color: var(--tib-ink);
    font: inherit;
    font-weight: var(--tib-name-weight);
    opacity: 1;
    background-color: transparent;
    background-image:
        linear-gradient(45deg, transparent 50%, var(--tib-sub) 50%),
        linear-gradient(135deg, var(--tib-sub) 50%, transparent 50%);
    background-size: 4px 4px;
    background-repeat: no-repeat;
    background-position: calc(100% - 12px) 50%, calc(100% - 8px) 50%;
    box-shadow: none;
    outline: none;
}

html body #extensionTopBarChatName:hover,
html body #extensionConnectionProfilesSelect:hover {
    background-color: var(--tib-hover);
}

html body #extensionTopBarChatName option,
html body #extensionConnectionProfilesSelect option {
    background: var(--tib-menu-bg);
    color: var(--tib-menu-ink);
    font-weight: normal;
}

/* 聊天名只占它要的宽度（最长那个聊天名），搜索框跟在后面，右边一组图标靠右 */
html body #extensionTopBarChatName {
    flex: 0 1 auto;
    max-width: 50%;
}

/* 搜索框 */
html body #extensionTopBarSearchInput {
    flex: 0 1 auto;
    min-width: 0;
    height: var(--tib-field-h);
    min-height: 0;
    margin: 0 auto 0 0;
    padding: 0 8px;
    border: 1px solid var(--tib-field-line);
    border-radius: var(--tib-field-radius);
    background: var(--tib-field-bg);
    color: var(--tib-ink);
    font: inherit;
    font-style: normal;
    opacity: 1;
    box-shadow: none;
    outline: none;
}

html body #extensionTopBarSearchInput:placeholder-shown {
    font-style: normal;
    opacity: 1;
    border-color: var(--tib-field-line);
}

html body #extensionTopBarSearchInput::placeholder {
    color: var(--tib-sub);
    opacity: 1;
}

html body #extensionTopBarSearchInput:focus {
    border-color: var(--tib-accent);
}

/* 放大镜：用渐变画（不写死颜色），一个圈 + 一道斜柄 */
html body #extensionTopBarSearchInput {
    --tib-ico-y: calc((var(--tib-field-h) - 14px) / 2 - 1px);
    padding-left: 26px;
    background-image:
        radial-gradient(circle closest-side, transparent 3.3px, var(--tib-sub) 3.6px 4.7px, transparent 5px),
        linear-gradient(45deg, transparent calc(50% - .8px), var(--tib-sub) calc(50% - .7px) calc(50% + .7px), transparent calc(50% + .8px));
    background-size: 10px 10px, 5px 5px;
    background-position: 9px var(--tib-ico-y), 16px calc(var(--tib-ico-y) + 8px);
    background-repeat: no-repeat;
}

/* 手机：一排塞不下，搜索平时收成一颗放大镜，点开（或里面有字）才展开 */
@media screen and (max-width: 1000px) {
    html body #extensionTopBarSearchInput {
        flex: none;
        width: var(--tib-field-h);
        max-width: none;
        padding: 0 0 0 var(--tib-field-h);
        transition: width .2s;
    }

    html body #extensionTopBarSearchInput:focus,
    html body #extensionTopBarSearchInput:not(:placeholder-shown) {
        width: 42vw;
        padding-right: 8px;
    }

    html body #extensionTopBarSearchInput:placeholder-shown:not(:focus)::placeholder {
        color: transparent;
    }

    html body #extensionTopBarSearchInput {
        background-position: calc(var(--tib-field-h) / 2 - 7px) var(--tib-ico-y), calc(var(--tib-field-h) / 2 + 1px) calc(var(--tib-ico-y) + 8px);
    }
}

html body #extensionConnectionProfilesStatus {
    color: var(--tib-sub);
    opacity: 1;
    font-size: inherit;
}

/* 搜到的字 */
html body #chat mark.highlight {
    background: var(--tib-mark-bg);
    color: var(--tib-mark-ink);
    border-radius: 2px;
}

/* 聊天列表侧栏（浮动小窗，套酒馆自己的 .draggable）：选中、悬停改用主题色 */
html body #extensionSideBar #extensionSideBarContainer .sideBarItem {
    border-color: var(--tib-line);
    border-radius: var(--tib-item-radius);
    font-family: var(--tib-font);
}

html body #extensionSideBar #extensionSideBarContainer .sideBarItem:hover {
    background-color: color-mix(in srgb, var(--tib-ink) 8%, transparent);
}

html body #extensionSideBar #extensionSideBarContainer .sideBarItem.selected {
    background-color: color-mix(in srgb, var(--tib-accent) 20%, transparent);
    border-color: var(--tib-accent);
}
/* ==== end shared/topinfobar.css ==== */
/* ==== themes/dorm/topbar.css ==== */
/* ---------------- 官方扩展「Chat Top Bar」：信笺抬头底下的一行，开着的按钮底下一道红笔 ---------------- */
:root {
    --tib-h: 34px;
    --tib-pad: var(--dm-pad-x);
    --tib-gap: 4px;
    --tib-bg: transparent;
    --tib-line: var(--dm-rule);
    --tib-ink: var(--dm-ink);
    --tib-sub: var(--dm-ink2);
    --tib-accent: var(--dm-red);
    --tib-font: var(--dm-font);
    --tib-size: 14px;
    --tib-name-weight: 700;
    --tib-btn: 26px;
    --tib-btn-radius: 0;
    --tib-hover: var(--dm-paper-low);
    --tib-field-bg: transparent;
    --tib-field-line: color-mix(in srgb, var(--dm-line), transparent 55%);
    --tib-field-radius: 0;
    --tib-field-h: 24px;
    --tib-menu-bg: var(--dm-paper);
    --tib-menu-ink: var(--dm-ink);
    --tib-mark-bg: color-mix(in srgb, var(--dm-note), transparent 10%);
}

html body #extensionTopBar > .right_menu_button.active {
    box-shadow: inset 0 -2px 0 var(--dm-red);
}
/* ==== end themes/dorm/topbar.css ==== */
